use strict; use warnings;
use POSIX ":sys_wait_h";

my $CPP  = "/workspace/dataset/test11_executable";
my $RUST = "/output/test11";

# each line of the cases file: tab-separated hex-encoded args
my $casefile = shift @ARGV or die "need casefile\n";
open(my $fh, "<", $casefile) or die $!;

sub run {
    my ($bin, @args) = @_;
    my $outf = "/tmp/wf-spec-2/.o.$$";
    my $pid = fork(); die "fork" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, ">", $outf) or exit 127;
        open(STDERR, ">", "/dev/null");
        exec($bin, @args) or exit 127;
    }
    waitpid($pid, 0);
    my $code = $? >> 8;
    my $sig  = $? & 127;
    local $/; open(my $g, "<", $outf) or die $!; binmode $g;
    my $data = <$g>; $data = "" unless defined $data; close $g; unlink $outf;
    return ($data, $code, $sig);
}

my ($n, $diff) = (0,0);
my @fails;
my @lines;
while (my $l = <$fh>) {
    chomp $l;
    next if $l =~ /^\s*$/;
    next if $l =~ /^#/;
    push @lines, $l;
}
close $fh;

for my $l (@lines) {
    my @hex = split /\t/, $l, -1;
    my @args = map { pack("H*", $_) } @hex;
    $n++;
    my ($co,$cc,$cs) = run($CPP, @args);
    my ($ro,$rc,$rs) = run($RUST, @args);
    my $same = ($co eq $ro) && ($cc == $rc) && ($cs == $rs);
    # field3 isolation: only meaningful for single-arg cases
    my $iso = "";
    if (@args == 1) {
        my $in = $args[0];
        my $nn = length($in);
        my $f1len = 4 + $nn;
        my $f2len = (substr($in,0,4) eq "xn--") ? $nn-4 : $nn;
        my $off3 = $f1len + 1 + $f2len + 1;
        my $f3c = substr($co, $off3, $f1len);
        my $f3r = length($ro) >= $off3+$f1len ? substr($ro, $off3, $f1len) : "<short>";
        my $exp = "xn--".$in;
        my $bound_ok = (length($co) > $off3+$f1len) && (substr($co,$off3-1,1) eq " ") && (substr($co,$off3+$f1len,1) eq " ");
        $iso = sprintf("f3ok=%d bound=%d f3eq=%d", ($f3c eq $exp)?1:0, $bound_ok?1:0, ($f3c eq $f3r)?1:0);
        if (!($f3c eq $exp) || !$bound_ok) {
            print "FIELD3-HYP-BREAK: args=", join(",", map {unpack("H*",$_)} @args), " iso=$iso\n";
            print "  cpp=", unpack("H*",$co), "\n";
        }
    }
    if (!$same) {
        $diff++;
        push @fails, [\@args, $co,$cc,$cs, $ro,$rc,$rs, $iso];
    }
}
print "PROBES=$n DIFFS=$diff\n";
for my $f (@fails) {
    my ($a,$co,$cc,$cs,$ro,$rc,$rs,$iso) = @$f;
    print "---- DIFF args=[", join(" | ", map { unpack("H*",$_) } @$a), "] $iso\n";
    print "  cpp code=$cc sig=$cs out=", unpack("H*",$co), "\n";
    print "  rst code=$rc sig=$rs out=", unpack("H*",$ro), "\n";
}
